create or replace function public.m08_combined_probe_v1(p_action text,p_parameters jsonb) returns jsonb language plpgsql security definer set search_path='' set statement_timeout='40s' set lock_timeout='35s' as $$
declare r jsonb;again jsonb;started timestamptz:=clock_timestamp();request_id uuid;
begin if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501';end if;if not exists(select 1 from public.admin_profiles where user_id='a8081000-0000-4000-8000-000000000001' and display_name='[M08 통합] 가짜 관리자' and is_active) or (select count(*) from public.students where created_by='a8081000-0000-4000-8000-000000000001' and note='M08-combined-a8081000: 실제 학생 아님' and status='active' and deleted_at is null)<>2 then raise exception 'm08_combined_fixture_guard';end if;
if p_action not in('compact','restore') or jsonb_typeof(p_parameters->'p_rows') is distinct from 'array' or jsonb_array_length(p_parameters->'p_rows')<>4
 or (select count(*) from jsonb_array_elements(p_parameters->'p_rows')e join private.historical_question_migrations m on m.id=(e->>'id')::uuid where m.assignment_id='a8081000-0000-4000-8000-000000000010' and m.kind='assignment')<>4 then raise exception 'm08_combined_parameter_guard';end if;
request_id:=(p_parameters->>'requestId')::uuid;if request_id is null then raise exception 'request id required';end if;
r:=private.apply_historical_question_batch_v1(request_id,p_action,p_parameters->>'p_archive_sha256',p_parameters->'p_rows');
again:=private.apply_historical_question_batch_v1(request_id,p_action,p_parameters->>'p_archive_sha256',p_parameters->'p_rows');
return jsonb_build_object('pid',pg_backend_pid(),'startedAt',started,'finishedAt',clock_timestamp(),'receipt',r,'replayEqual',r=again);
end $$;
revoke all on function public.m08_combined_probe_v1(text,jsonb) from public,anon,authenticated;grant execute on function public.m08_combined_probe_v1(text,jsonb) to service_role;notify pgrst,'reload schema';

